from pathlib import Path
from hashlib import sha256
root = Path('products/distribution/sqlite-community-directory')
for name in ('operator-submission-packet.md', 'director-referral-candidate.diff'):
    path = root / name
    if path.is_file():
        print(name, sha256(path.read_bytes()).hexdigest())
for path in sorted(root.glob('*.json')):
    if path.stat().st_size > 12000:
        continue
    text = path.read_text()
    if any(term in path.stem for term in ('readiness', 'verdict', 'decision', 'binding')) or ('verdict' in text.lower() and 'independent' in path.stem):
        print(path.name, text[:4500])
